"8 − 3 = 5, 6/7 − 2/7 = 4/7. Осталось 5 4/7 кг.": "8 − 3 = 5, 6/7 − 2/7 = 4/7. 5 4/7 кг қалды.",
"Диаметр монеты 24 мм. Чему равны 2/3 диаметра?": "Теңгенің диаметрі 24 мм. Диаметрдің 2/3-і неге тең?",
