"Диаметр всегда проходит через центр окружности.": "Диаметр әрқашан шеңбердің центрі арқылы өтеді.",
"Можно: больше та часть, у которой сектор больше.": "Болады: сектор үлкен болатын бөлік үлкен.",
"Смотрим точку для времени 2 ч: расстояние 30 км.": "Уақыты 2 сағат болатын нүктені қараймыз: қашықтық 30 км.",
"Оба движутся в одном направлении по одной линии.": "Екеуі де бір сызық бойымен бір бағытта қозғалады.",
"Трое друзей могут встать в ряд шестью способами.": "Үш дос қатарға алты тәсілмен тұра алады.",
"Неверно: знаменатель остаётся 9. Правильно: 4/9.": "Бұрыс: бөлімі 9 болып қалады. Дұрысы: 4/9.",
"Чтобы найти целое, надо часть умножить на дробь.": "Бүтінді табу үшін бөлікті бөлшекке көбейту керек.",
"Если кошка уже у Аяна, у Берика её быть не может": "Егер мысық Аянда болса, Берікте болуы мүмкін емес",
"Это тоже графики зависимости величины от времени.": "Бұл да шаманың уақытқа тәуелділік графиктері.",
"Оба начинают в одном месте и едут в одну сторону.": "Екеуі де бір жерден шығып, бір бағытқа жүреді.",
"на соответствие: у каждого из троих своё животное": "сәйкестікке: үшеуінің әрқайсысында өз жануары бар",
"Запиши смешанное число 3 2/5 неправильной дробью.": "3 2/5 аралас санын бұрыс бөлшек етіп жаз.",
"В банке 12 кг мёда. Продали 1/4. Сколько продали?": "Құтыда 12 кг бал бар. 1/4-і сатылды. Қанша сатылды?",
